"""Task-local inspection: list workspace files and sqlite DB schema (read-only)."""
import os
import sqlite3

for entry in sorted(os.listdir(".")):
    print(entry)

print("---")
for name in sorted(os.listdir(".")):
    if name.endswith((".db", ".sqlite", ".sqlite3")):
        path = os.path.join(".", name)
        print(f"DB: {path}")
        try:
            conn = sqlite3.connect(path)
            cur = conn.cursor()
            tables = cur.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
            for (table,) in tables:
                print(f"  table: {table}")
                for row in cur.execute(f"PRAGMA table_info({table})"):
                    print(f"    col: {row}")
                print(f"  rows: {cur.execute(f'SELECT COUNT(*) FROM {table}').fetchone()[0]}")
            conn.close()
        except sqlite3.Error as exc:
            print(f"  error: {exc}")

